const slug = (text) =>
  text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
const names = ['Inês', 'Tomás', 'Beatriz', 'Raul', 'Nina', 'Bento'];
const surnames = [
  'Valença',
  'Farias',
  'Souto',
  'Prado',
  'Moura',
  'Lemos',
  'Vieira',
  'Gouveia',
  'Tavares',
  'Pimentel',
  'Duarte',
  'Ramos',
  'Couto',
  'Barreto',
  'Paiva',
  'Aguiar',
  'Guimarães',
  'Bastos',
  'Siqueira',
  'Lacerda',
  'Assunção',
  'Pacheco',
  'Pinheiro',
  'Macedo',
  'Rezende',
  'Alencar',
  'Falcão',
  'Freitas',
  'Queiroz',
  'Peixoto',
  'Andrade',
  'Seabra',
];
const accents = ['#315b72', '#685334', '#496745', '#715268', '#3f6270', '#785043'];

export function longTailContent({ brands, entities, add, url, epoch, limit }) {
  const rows = groups
    .flatMap(([category, layout, visual, records], group) =>
      records
        .trim()
        .split('\n')
        .map((record, within) => ({
          category,
          layout,
          visual,
          group,
          within,
          fields: record.split('|'),
        })),
    )
    .slice(0, limit);
  for (const [index, row] of rows.entries()) {
    const [name, title, lead, observation] = row.fields;
    if (!observation || row.fields.length !== 4)
      throw new Error(`Incomplete long-tail source: ${name}`);
    const id = `local-${slug(name)}`;
    row.id = id;
    row.author = `${names[row.within]} ${surnames[row.group % surnames.length]}`;
    const domain = `${slug(name).replaceAll('-', '')}.${row.layout === 'personal' ? 'blog' : 'com'}`;
    // 3 × 3 × 3 × 2 × 4 = 216 structural identities, each stable across page reloads.
    const identity = {
      typography: ['sans', 'serif', 'mono'][index % 3],
      header: ['compact', 'masthead', 'band'][Math.floor(index / 3) % 3],
      cards: ['grid', 'rows', 'ledger'][Math.floor(index / 9) % 3],
      density: ['airy', 'dense'][Math.floor(index / 27) % 2],
      surface: ['paper', 'plain', 'tinted', 'lined'][Math.floor(index / 54) % 4],
    };
    brands.push({
      id,
      name,
      domain,
      platform:
        row.layout === 'personal' ? 'BLOG' : row.layout === 'corporate' ? 'CORPORATE' : 'EDITORIAL',
      layout: row.layout,
      depth: 'LONG_TAIL',
      identity,
      accent: accents[row.within],
      mark: name
        .split(' ')
        .filter((w) => w.length > 2)
        .slice(0, 2)
        .map((w) => w[0])
        .join(''),
      tagline: `${row.category} por ${row.author}.`,
      voice: `Um arquivo de ${row.category.toLowerCase()} mantido por ${row.author}, com relatos de campo e notas de revisão.`,
      navigation: [
        { label: 'Leituras', url: `https://www.${domain}/?category=Leituras` },
        { label: 'Caderno de campo', url: `https://www.${domain}/?category=Registros` },
      ],
    });
    entities.push({
      id,
      name,
      kind: 'Publisher',
      aliases: [domain],
      description: lead,
      relations: [{ kind: 'covers', target: `field-${row.group}` }],
    });
    if (!entities.some((e) => e.id === `field-${row.group}`))
      entities.push({
        id: `field-${row.group}`,
        name: row.category,
        kind: 'Topic',
        aliases: [],
        description: `Fontes locais sobre ${row.category.toLowerCase()}.`,
        relations: [],
      });
    row.title = title;
  }
  for (const row of rows) {
    const [name, title, lead, observation] = row.fields;
    const neighbor = rows.find((r) => r.group === row.group && r.id !== row.id);
    const entry = url(row.id, '/leitura/registro');
    const notebook = url(row.id, '/caderno/observacao');
    const place = ['Porto Claro', 'Santa Aurora', 'Vila Horizonte'][row.group % 3];
    const links = [
      { label: 'Caderno de campo', url: notebook },
      ...(neighbor
        ? [{ label: neighbor.fields[0], url: url(neighbor.id, '/leitura/registro') }]
        : []),
    ];
    const extra = {
      author: row.author,
      publishedAt: epoch - 86400,
      visual: row.visual,
      entities: [row.id, `field-${row.group}`],
      keywords: [row.category],
      links,
    };
    add(
      row.id,
      '/leitura/registro',
      title,
      lead,
      'Leituras',
      [
        { kind: 'paragraph', text: lead },
        { kind: 'heading', text: 'Ficha da publicação' },
        {
          kind: 'table',
          headings: ['Referência', 'Registro'],
          rows: [
            ['Fonte', name],
            ['Responsável', row.author],
            ['Área', row.category],
            ['Local da publicação', place],
          ],
        },
        { kind: 'link', label: 'O detalhe observado e as notas do registro', url: notebook },
      ],
      { kind: 'article', readingMinutes: 1 },
      extra,
    );
    add(
      row.id,
      '/caderno/observacao',
      `${name}: uma observação do caderno`,
      observation,
      'Registros',
      [
        { kind: 'paragraph', text: observation },
        { kind: 'quote', text: title, attribution: `Publicação relacionada, ${name}` },
        {
          kind: 'table',
          headings: ['Acervo', 'Identificação'],
          rows: [
            ['Caderno', `${row.category} / ${row.within + 1}`],
            ['Assinatura', row.author],
            ['Publicação de origem', name],
          ],
        },
        { kind: 'link', label: 'Ler o relato completo', url: entry },
      ],
      { kind: 'article', readingMinutes: 1 },
      { ...extra, links: [{ label: title, url: entry }, ...links.slice(1)] },
    );
  }
}
